pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: give owner some ether, give contract some ether via multiplicate, then use a non-owner to call withdraw
        address owner = c.Owner();
        address nonOwner = address(0xbeef);

        // Fund the contract with 5 ether from owner via multiplicate (msg.value >= contract balance to trigger the require
        // we start with contract balance = 0, send 5 ether -> condition true
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        c.multiplicate{value: 5 ether}(nonOwner);  // contract gets 5 ether, then sends 5 ether to nonOwner? Actually code sends address(this).balance+msg.value = 5+5=10 to nonOwner but contract only had 0, so after receiving 5 it sends 10? Wait careful: initially balance=0, msg.value=5, condition 5>=0 true; then payable(adr).transfer(0+5)=5; contract ends with 0 eth, nonOwner gets 5.
        // So contract balance is now 0. Let's fund it differently: use Command from owner to send ether to contract
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        (bool success, ) = address(c).call{value: 5 ether}(""); // receive() accepts, contract balance = 5
        require(success);

        // Now contract has 5 ether.
        // Bug: nonOwner can call withdraw() and drain contract to owner (owner gets 5 ether).
        // Reference: nonOwner call withdraw() reverts because msg.sender != Owner.
        vm.prank(nonOwner);
        // Trying to call withdraw via the public function; we'll check if it reverts or not by comparing contract balance after call.
        // We'll directly use a low-level call to catch revert
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        // In reference, ok == false (revert). In bug, ok == true and contract balance becomes 0.
        // Assert that the reference's behavior is: contract balance remains 5 (since revert).
        // But we need a concrete fact to assert: we can check address(c).balance after call.
        // For reference, balance unchanged (5 ether). For bug, balance becomes 0.
        // We are testing on the reference (the contract in setup is reference, we assume). Actually we are running the test on the reference C; the test should pass on reference. So we assert that after the nonOwner withdraw call, contract balance is still 5 ether.
        assertTrue(address(c).balance == 5 ether);
    }
}

