pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = c.Owner();
        address nonOwner = address(0x1234);

        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Fund nonOwner with 1 ether
        vm.deal(nonOwner, 1 ether);

        // NonOwner calls multiplicate with msg.value = address(this).balance (1 ether)
        vm.prank(nonOwner);
        c.multiplicate{value: 1 ether}(nonOwner);

        // Now contract balance is 0 (all sent to nonOwner)
        // Try to call withdraw as nonOwner
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // Reference: withdraw reverts for nonOwner (ok == false)
        // Bug: withdraw succeeds (ok == true)
        // Assert that the reference passes (ok == false)
        assertTrue(!ok, "withdraw should revert for nonOwner");
    }
}

