pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;
    address nonOwner = address(0x1234);

    function setUp() public {
        c = new C();
        owner = c.Owner();
    }

    function testRegression_property() public {
        // Give owner some ether to start
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success);

        // Non-owner sends 1 wei via multiplicate (not triggering the if branch)
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        c.multiplicate{value: 1 wei}(address(0x5678));

        // Non-owner calls Command with 1 wei to send to owner
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        c.Command{value: 1 wei}(owner, "");

        // Now non-owner tries to call withdraw
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        // In reference, require(msg.sender == Owner) reverts => ok is false
        // In buggy, no require => ok is true and contract balance becomes 0
        assertTrue(!ok);
    }
}

