import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether via fallback
        vm.deal(address(c), 1 ether);
        // Change Owner via Command to address(1) (any address different from msg.sender)
        address newOwner = address(1);
        bytes memory emptyData = "";
        vm.prank(address(this));
        c.Command(newOwner, emptyData);
        // Now call multiplicate with msg.value = 0 (less than contract balance)
        // This triggers if-condition (0 >= 1 ether is false) so the require block is skipped entirely
        vm.prank(address(this));
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("multiplicate(address)", address(2)));
        // In reference: if condition is false, so function returns without revert -> ok == true
        // In bug: if condition is false, so function returns without revert -> ok == true
        // Wait, we need a scenario where the bug diverges. Let's adjust.
        // Try: call multiplicate with msg.value = 1 ether (exactly balance)
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        (bool ok2, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("multiplicate(address)", address(2)));
        // In reference: if (1 ether >= 1 ether) true -> require(balance+1 ether >= balance) -> true (no overflow) -> transfer(2 ether) succeeds -> no revert -> ok2 == true
        // In bug: if (1 ether >= 1 ether) true -> require(balance+1 ether < balance) -> false (overflow check passes, so require fails) -> revert -> ok2 == false
        assertTrue(ok2 == true);
    }
}

