        // Now contract balance = 2 ether, receiver now has 2 ether
        uint256 balanceBefore = address(c).balance;

        // Call multiplicate with msg.value = 2 ether
        vm.deal(owner, 2 ether);
        vm.prank(owner);
        c.multiplicate{value: 2 ether}(receiver);

        // After reference: contract self-destructed (balance 0)
        // After bug: contract sends only 2 ether, keeps 2 ether
        assertTrue(address(c).balance != 2 ether);
    }
}

